import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Statistic, Space, Spin, Empty, message } from 'antd';
import { UserOutlined, InteractionOutlined, DollarOutlined } from '@ant-design/icons';
import { Column, Pie } from '@ant-design/plots';
import { API_BASE_URL } from '../../../utils/api';
import styles from './SalesOverview.module.css';

// 所有可能的客戶階段及對應顏色
const ALL_STAGES = {
  potential: { name: '潛在客戶', color: '#1890ff' },
  contacted: { name: '已聯繫', color: '#722ed1' },
  negotiating: { name: '洽談中', color: '#fa8c16' },
  contract_signed: { name: '已簽約', color: '#13c2c2' },
  payment_received: { name: '已收款', color: '#52c41a' },
  completed: { name: '已完成', color: '#2f54eb' },
  lost: { name: '已流失', color: '#f5222d' }
};

const SalesOverview = () => {
  const [loading, setLoading] = useState(true);
  const [overviewData, setOverviewData] = useState({
    totalCustomers: 0,
    totalInteractions: 0,
    totalDeals: 0,
    totalRevenue: 0,
    customerStages: [],
    customerSources: []
  });

  // 獲取當前登入用戶資訊
  const getCurrentUser = () => {
    const userStr = localStorage.getItem('salesStaff');
    if (userStr) {
      try {
        return JSON.parse(userStr);
      } catch (error) {
        console.error('解析用戶資訊失敗:', error);
        return null;
      }
    }
    return null;
  };

  const fetchOverviewData = async () => {
    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      if (!currentUser) {
        message.error('未找到用戶資訊，請重新登入');
        return;
      }

      // 獲取該銷售人員的所有客戶
      const customersResponse = await fetch(
        `${API_BASE_URL}/api/customers?filters[sales_staff][id]=${currentUser.id}&populate=*`
      );
      
      if (!customersResponse.ok) {
        throw new Error('獲取客戶資料失敗');
      }
      
      const customersData = await customersResponse.json();
      const customers = customersData.data || [];

      // 獲取該銷售人員的所有互動記錄
      const interactionsResponse = await fetch(
        `${API_BASE_URL}/api/interactions?filters[sales_staff][id]=${currentUser.id}&populate=*`
      );
      
      if (!interactionsResponse.ok) {
        throw new Error('獲取互動記錄失敗');
      }
      
      const interactionsData = await interactionsResponse.json();
      const interactions = interactionsData.data || [];

      // 計算客戶階段分布
      const stages = {};
      Object.keys(ALL_STAGES).forEach(stage => {
        stages[stage] = 0;
      });

      customers.forEach(customer => {
        if (!customer.attributes) {
          console.log('Customer missing attributes:', customer);
          return;
        }
        const status = customer.attributes.status;
        if (status && stages.hasOwnProperty(status)) {
          stages[status]++;
        }
      });

      const customerStages = Object.entries(ALL_STAGES).map(([key, value]) => {
        const count = stages[key] || 0;
        const percentage = customers.length > 0 ? ((count / customers.length) * 100).toFixed(1) : '0.0';
        return {
          stage: value.name,
          count: count,
          percentage: percentage
        };
      });

      // 計算客戶來源分布
      const sourceCount = {};
      customers.forEach(customer => {
        if (!customer?.attributes?.source) {
          sourceCount['其他'] = (sourceCount['其他'] || 0) + 1;
        } else {
          const source = getSourceText(customer.attributes.source);
          sourceCount[source] = (sourceCount[source] || 0) + 1;
        }
      });

      const customerSources = Object.entries(sourceCount).map(([source, count]) => {
        const percentage = customers.length > 0 ? ((count / customers.length) * 100).toFixed(1) : '0.0';
        return {
          source,
          count,
          percentage
        };
      }).sort((a, b) => b.count - a.count);

      // 計算成交金額
      const totalRevenue = interactions
        .filter(interaction => interaction.attributes.is_deal)
        .reduce((sum, interaction) => sum + (parseFloat(interaction.attributes.deal_amount) || 0), 0);

      // 計算成交數量
      const totalDeals = interactions.filter(interaction => interaction.attributes.is_deal).length;

      setOverviewData({
        totalCustomers: customers.length,
        totalInteractions: interactions.length,
        totalDeals,
        totalRevenue,
        customerStages,
        customerSources
      });
    } catch (error) {
      console.error('獲取總覽資料失敗:', error);
      message.error('獲取資料失敗，請稍後再試');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOverviewData();
  }, []);

  const getSourceText = (source) => {
    const sourceMap = {
      'website': '官網',
      'referral': '轉介紹',
      'social_media': '社群媒體',
      'event': '活動',
      'advertisement': '廣告',
      'other': '其他',
      'unknown': '未知'
    };
    return sourceMap[source] || source;
  };

  const stageColumnConfig = {
    data: overviewData.customerStages,
    xField: 'stage',
    yField: 'count',
    colorField: 'stage',
    color: ['#1890ff', '#722ed1', '#fa8c16', '#13c2c2', '#52c41a', '#2f54eb', '#f5222d'],
    label: false,
    columnStyle: {
      radius: [4, 4, 0, 0],
    },
    xAxis: {
      label: {
        autoRotate: true,
        autoHide: false,
        autoEllipsis: true
      }
    },
    yAxis: {
      title: {
        text: '客戶數量'
      }
    },
    tooltip: {
      customContent: (title, items) => {
        const item = items?.[0];
        if (!item?.data) return '';
        return `
          <div style="padding: 4px 8px;">
            <div style="margin-bottom: 4px;">${item.data.stage}</div>
            <div>客戶數量: ${item.data.count} 人</div>
            <div>占比: ${item.data.percentage}%</div>
          </div>
        `;
      }
    },
    interactions: [{ type: 'element-active' }],
    state: {
      active: {
        style: {
          shadowColor: 'rgba(0,0,0,0.25)',
        },
      },
    },
  };

  const sourcePieConfig = {
    appendPadding: 10,
    data: overviewData.customerSources,
    angleField: 'count',
    colorField: 'source',
    radius: 0.8,
    label: {
      type: 'inner',
      offset: '-30%',
      content: ({ percent }) => `${(percent * 100).toFixed(0)}%`,
      style: {
        fontSize: 14,
        textAlign: 'center',
      },
    },
    legend: {
      position: 'bottom',
    },
    interactions: [{ type: 'element-active' }],
    tooltip: {
      formatter: (datum) => {
        return { name: datum.source, value: datum.count };
      }
    }
  };

  if (loading) {
    return (
      <div className={styles.loadingContainer}>
        <Spin size="large" />
        <p>載入中...</p>
      </div>
    );
  }

  return (
    <div className={styles.overview}>
      <div className={styles.overviewContainer}>
        <div className={styles.pageTitle}>
          <h2>銷售總覽</h2>
        </div>
        
        <Row gutter={[16, 16]} className={styles.statsCards}>
          <Col xs={24} sm={12} md={8}>
            <Card className={styles.statCard}>
              <Statistic
                title="總客戶數"
                value={overviewData.totalCustomers}
                prefix={<UserOutlined />}
                valueStyle={{ color: '#3f8600' }}
              />
            </Card>
          </Col>
          <Col xs={24} sm={12} md={8}>
            <Card className={styles.statCard}>
              <Statistic
                title="總互動次數"
                value={overviewData.totalInteractions}
                prefix={<InteractionOutlined />}
                valueStyle={{ color: '#1890ff' }}
              />
            </Card>
          </Col>
          <Col xs={24} sm={12} md={8}>
            <Card className={styles.statCard}>
              <Statistic
                title="成交數量"
                value={overviewData.totalDeals}
                prefix={<DollarOutlined />}
                valueStyle={{ color: '#faad14' }}
              />
            </Card>
          </Col>
        </Row>

        <Row gutter={[16, 16]} className={styles.chartsRow}>
          <Col xs={24} md={12}>
            <Card title="客戶階段分布" className={styles.chartCard}>
              {overviewData.customerStages.length > 0 ? (
                <Column {...stageColumnConfig} />
              ) : (
                <div className={styles.emptyChartContainer}>
                  <Empty description="暫無數據" />
                </div>
              )}
            </Card>
          </Col>
          <Col xs={24} md={12}>
            <Card title="客戶來源分布" className={styles.chartCard}>
              {overviewData.customerSources.length > 0 ? (
                <Pie {...sourcePieConfig} />
              ) : (
                <div className={styles.emptyChartContainer}>
                  <Empty description="暫無數據" />
                </div>
              )}
            </Card>
          </Col>
        </Row>
      </div>
    </div>
  );
};

export default SalesOverview; 