import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Statistic, Space, DatePicker, Select, Spin, Empty } from 'antd';
import { ArrowUpOutlined, ArrowDownOutlined, UserOutlined, DollarOutlined, PieChartOutlined } from '@ant-design/icons';
import { API_BASE_URL } from '../../../utils/api';
import styles from './Overview.module.css';
import { Column, Pie } from '@ant-design/plots';

const { RangePicker } = DatePicker;

// 所有可能的客戶階段及對應顏色
const ALL_STAGES = {
  potential: { name: '潛在客戶', color: '#1890ff' },
  contacted: { name: '已聯繫', color: '#722ed1' },
  negotiating: { name: '洽談中', color: '#fa8c16' },
  contract_signed: { name: '已簽約', color: '#13c2c2' },
  payment_received: { name: '已收款', color: '#52c41a' },
  completed: { name: '已完成', color: '#2f54eb' },
  lost: { name: '已流失', color: '#f5222d' }
};

const Overview = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalCustomers: 0,
    newCustomers: 0,
    totalDealAmount: 0,
    monthlyDealAmount: 0,
    conversionRate: 0,
    lastMonthConversionRate: 0
  });
  const [stageDistribution, setStageDistribution] = useState([]);
  const [dealTrend, setDealTrend] = useState([]);
  const [sourceDistribution, setSourceDistribution] = useState([]);

  useEffect(() => {
    fetchOverviewData();
  }, []);

  const fetchOverviewData = async () => {
    try {
      setLoading(true);
      
      // 獲取客戶統計
      const customersResponse = await fetch(`${API_BASE_URL}/api/customers?populate=*`);
      const customersData = await customersResponse.json();
      const customers = customersData.data || [];

      console.log('Raw customers data:', customers);

      // 獲取互動記錄（包含成交資訊）
      const interactionsResponse = await fetch(`${API_BASE_URL}/api/interactions?populate=*`);
      const interactionsData = await interactionsResponse.json();
      const interactions = interactionsData.data || [];

      // 計算總客戶數和本月新增
      const now = new Date();
      const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
      const newCustomers = customers.filter(c => 
        new Date(c.attributes.createdAt) >= monthStart
      ).length;

      // 計算成交金額
      const deals = interactions.filter(i => 
        i.attributes.is_deal && 
        i.attributes.deal_amount && 
        (i.attributes.status === 'completed' || i.attributes.status === 'payment_received')
      );

      const totalDealAmount = deals.reduce((sum, deal) => 
        sum + (parseFloat(deal.attributes.deal_amount) || 0), 0
      );

      const monthlyDeals = deals.filter(deal => 
        new Date(deal.attributes.payment_date) >= monthStart
      );

      const monthlyDealAmount = monthlyDeals.reduce((sum, deal) => 
        sum + (parseFloat(deal.attributes.deal_amount) || 0), 0
      );

      // 計算轉換率
      const closedCustomers = new Set(deals.map(deal => deal.attributes.customer.data.id));
      const conversionRate = customers.length > 0 ? (closedCustomers.size / customers.length) * 100 : 0;

      // 計算上月轉換率
      const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);
      const lastMonthDeals = deals.filter(deal => {
        const dealDate = new Date(deal.attributes.payment_date);
        return dealDate >= lastMonthStart && dealDate <= lastMonthEnd;
      });
      const lastMonthClosedCustomers = new Set(lastMonthDeals.map(deal => 
        deal.attributes.customer.data.id
      ));
      const lastMonthConversionRate = customers.length > 0 ? (lastMonthClosedCustomers.size / customers.length) * 100 : 0;

      // 階段分布數據處理
      const stages = {};
      Object.keys(ALL_STAGES).forEach(stage => {
        stages[stage] = 0;
      });

      customers.forEach(customer => {
        if (!customer.attributes) {
          console.log('Customer missing attributes:', customer);
          return;
        }
        const status = customer.attributes.status;
        if (status && stages.hasOwnProperty(status)) {
          stages[status]++;
        }
      });

      const stageData = Object.entries(ALL_STAGES).map(([key, value]) => {
        const count = stages[key] || 0;
        const percentage = customers.length > 0 ? ((count / customers.length) * 100).toFixed(1) : '0.0';
        return {
          stage: value.name,
          count: count,
          percentage: percentage
        };
      });

      // 來源分布數據處理
      const sourceCount = {};
      customers.forEach(customer => {
        if (!customer?.attributes?.source) {
          sourceCount['其他'] = (sourceCount['其他'] || 0) + 1;
        } else {
          const source = getSourceText(customer.attributes.source);
          sourceCount[source] = (sourceCount[source] || 0) + 1;
        }
      });

      console.log('Source counts:', sourceCount);

      const sourceData = Object.entries(sourceCount).map(([source, count]) => {
        const percentage = customers.length > 0 ? ((count / customers.length) * 100).toFixed(1) : '0.0';
        const item = {
          source,
          count,
          percentage
        };
        console.log('Source data item:', item);
        return item;
      }).sort((a, b) => b.count - a.count); // 按數量排序

      console.log('Final source data:', sourceData);

      // 計算成交趨勢（按月）
      const dealsByMonth = {};
      deals.forEach(deal => {
        const date = new Date(deal.attributes.payment_date);
        const monthKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
        dealsByMonth[monthKey] = (dealsByMonth[monthKey] || 0) + parseFloat(deal.attributes.deal_amount || 0);
      });

      const trendData = Object.entries(dealsByMonth)
        .map(([month, amount]) => ({
          month,
          amount
        }))
        .sort((a, b) => a.month.localeCompare(b.month));

      setStats({
        totalCustomers: customers.length,
        newCustomers,
        totalDealAmount,
        monthlyDealAmount,
        conversionRate,
        lastMonthConversionRate
      });

      setStageDistribution(stageData);
      setSourceDistribution(sourceData);
      setDealTrend(trendData);

    } catch (error) {
      console.error('Error fetching overview data:', error);
      console.error('Error details:', error.message);
    } finally {
      setLoading(false);
    }
  };

  const getSourceText = (source) => {
    const sourceMap = {
      'event': '活動',
      'website': '網站',
      'referral': '推薦',
      'other': '其他'
    };
    return sourceMap[source] || '其他';
  };

  const stageColumnConfig = {
    data: stageDistribution,
    xField: 'stage',
    yField: 'count',
    colorField: 'stage', // 新增這行
    color: ['#1890ff', '#722ed1', '#fa8c16', '#13c2c2', '#52c41a', '#2f54eb', '#f5222d'],
    label: false, // 移除柱狀圖內的數字
    columnStyle: {
      radius: [4, 4, 0, 0],
    },
    xAxis: {
      label: {
        autoRotate: true,
        autoHide: false,
        autoEllipsis: true
      }
    },
    yAxis: {
      title: {
        text: '客戶數量'
      }
    },
    tooltip: {
      customContent: (title, items) => {
        const item = items?.[0];
        if (!item?.data) return '';
        return `
          <div style="padding: 4px 8px;">
            <div style="margin-bottom: 4px;">${item.data.stage}</div>
            <div>客戶數量: ${item.data.count} 人</div>
            <div>占比: ${item.data.percentage}%</div>
          </div>
        `;
      }
    },
    interactions: [{ type: 'element-active' }],
    state: {
      active: {
        style: {
          shadowColor: 'rgba(0,0,0,0.25)',
        },
      },
    },
  };

  const pieConfig = {
    appendPadding: 10,
    data: sourceDistribution,
    angleField: 'count',
    colorField: 'source',
    radius: 0.8,
    legend: {
      position: 'bottom',
    },
    tooltip: {
      formatter: (datum) => {
        console.log('Pie tooltip datum:', datum);
        return {
          name: datum.source,
          value: `客戶數：${datum.count} 人`
        };
      }
    },
    statistic: {
      title: false,
      content: {
        style: {
          whiteSpace: 'pre-wrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
        },
      },
    },
    label: {
      autoRotate: false,
      formatter: (datum) => `${datum.source}\n${datum.count} 人`,
      style: {
        fontSize: 12,
        textAlign: 'center',
      },
    }
  };

  const columnConfig = {
    data: dealTrend,
    xField: 'month',
    yField: 'amount',
    label: {
      position: 'top',
      style: {
        fill: '#666',
        fontSize: 12
      },
      formatter: (v) => `${(v.amount / 10000).toFixed(1)}萬`
    },
    meta: {
      month: {
        alias: '月份'
      },
      amount: {
        alias: '成交金額'
      }
    },
    xAxis: {
      label: {
        autoRotate: true,
        autoHide: false,
        autoEllipsis: true
      }
    },
    color: '#1890ff'
  };

  if (loading) {
    return (
        <div className={styles.loadingContainer}>
          <Spin size="large" />
      </div>
    );
  }

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h2>總覽</h2>
        <Space size="middle">
          <RangePicker 
            placeholder={['開始日期', '結束日期']}
          />
          <Select
            placeholder="選擇業務員"
            style={{ width: 200 }}
            allowClear
          >
            {/* 業務員選項將從API獲取 */}
          </Select>
        </Space>
      </div>

      <Row gutter={[16, 16]}>
        <Col xs={24} sm={12} md={8}>
          <Card className={styles.statCard}>
            <Statistic
              title="總客戶數"
              value={stats.totalCustomers}
              prefix={<UserOutlined style={{ color: '#1890ff' }} />}
            />
            <div className={styles.smallText}>
              本月新增: {stats.newCustomers}
            </div>
          </Card>
        </Col>
        <Col xs={24} sm={12} md={8}>
          <Card className={styles.statCard}>
            <Statistic
              title="總成交金額"
              value={stats.totalDealAmount}
              precision={2}
              prefix={<DollarOutlined style={{ color: '#52c41a' }} />}
            />
            <div className={styles.smallText}>
              本月: {stats.monthlyDealAmount.toFixed(2)}
            </div>
          </Card>
        </Col>
        <Col xs={24} sm={12} md={8}>
          <Card className={styles.statCard}>
            <Statistic
              title="轉換率"
              value={stats.conversionRate}
              precision={2}
              prefix={<PieChartOutlined style={{ color: '#722ed1' }} />}
              suffix="%"
            />
            <div className={styles.smallText}>
              {stats.conversionRate >= stats.lastMonthConversionRate ? (
                <ArrowUpOutlined style={{ color: '#52c41a' }} />
              ) : (
                <ArrowDownOutlined style={{ color: '#f5222d' }} />
              )}
              <span style={{ marginLeft: '4px' }}>
                較上月: {Math.abs(stats.conversionRate - stats.lastMonthConversionRate).toFixed(2)}%
              </span>
            </div>
          </Card>
        </Col>
      </Row>
      
      <Row gutter={[16, 16]} style={{ marginTop: '16px' }}>
        <Col xs={24} lg={12}>
          <Card title="客戶階段分布" className={styles.chartCard}>
            {stageDistribution.length > 0 ? (
              <div style={{ height: '320px', padding: '20px 0' }}>
                <Column {...stageColumnConfig} />
              </div>
            ) : (
              <Empty />
            )}
                </Card>
              </Col>
          <Col xs={24} lg={12}>
            <Card title="客戶來源分布" className={styles.chartCard}>
              {sourceDistribution.length > 0 ? (
                <div style={{ height: '320px', padding: '20px 0' }}>
                  <Pie {...pieConfig} />
                </div>
              ) : (
                <Empty />
              )}
                </Card>
              </Col>
            </Row>
            
      <Row gutter={[16, 16]} style={{ marginTop: '16px' }}>
        <Col span={24}>
          <Card title="成交金額趨勢" className={styles.chartCard}>
            {dealTrend.length > 0 ? (
              <div style={{ height: '320px', padding: '20px 0' }}>
                <Column {...columnConfig} />
              </div>
            ) : (
              <Empty />
            )}
      </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Overview; 